public protocol CoreRuntimeProtocol: AnyObject, Sendable {

    /**
     * P6-7: real ACK tracking, replacing the P6-6 fire-and-forget placeholder. Fast: identity/
     * closed checks and request construction run synchronously; only the genuine ACK round trip
     * is pushed onto a background thread inside the scope. The outcome arrives later as a
     * `flagSettingsApplied` terminal-class event on the subscription, correlated by this same
     * `request_id` -- charter §8.2's command+event shape, mirroring `agent_interrupt_turn` exactly.
     */
    func agentApplyModelAndEffort(identity: RuntimeIdentity, scopeId: String, model: String?, effort: String?, disposition: AgentClaudeFlagSettingsDispositionV1) throws  -> AgentClaudeFlagSettingsReceiptV1

    /**
     * Contract §4: fenced by `turn_generation`, no pre-check (design §5.3 -- the pre-check is
     * *removed*, not made remote). Fast: the generation/in-flight classification runs
     * synchronously; only a genuine ACK round trip (when the named generation is current and a
     * turn is in flight) is pushed onto a background thread inside the scope.
     */
    func agentInterruptTurn(identity: RuntimeIdentity, scopeId: String, turnGeneration: UInt64, reason: String) throws  -> AgentClaudeInterruptReceiptV1

    func agentOpenScope(identity: RuntimeIdentity, config: CoreAgentClaudeScopeConfigV1) throws  -> AgentClaudeScopeHandleV1

    func agentProviderAcpCancel(identity: RuntimeIdentity, scopeId: String, cancellationToken: String) throws  -> Bool

    func agentProviderAcpNotify(identity: RuntimeIdentity, scopeId: String, method: String, params: Data?, expectedSessionGeneration: UInt64?) throws  -> CoreAgentProviderAcpControlReceiptV1

    func agentProviderAcpRequest(identity: RuntimeIdentity, scopeId: String, method: String, params: Data?, timeoutMilliseconds: UInt64?, cancellationToken: String?) throws  -> CoreAgentProviderAcpResponseV1

    func agentProviderAcpRespond(identity: RuntimeIdentity, scopeId: String, requestId: Data, result: Data) throws  -> CoreAgentProviderAcpControlReceiptV1

    func agentProviderAcpRespondError(identity: RuntimeIdentity, scopeId: String, requestId: Data, code: Int64, message: String, data: Data?) throws  -> CoreAgentProviderAcpControlReceiptV1

    func agentProviderAcpState(identity: RuntimeIdentity, scopeId: String) throws  -> CoreAgentProviderAcpSessionStateV1

    func agentProviderCodexCancel(identity: RuntimeIdentity, scopeId: String, cancellationToken: String) throws  -> Bool

    func agentProviderCodexNotify(identity: RuntimeIdentity, scopeId: String, method: String, params: Data?) throws  -> UInt64

    func agentProviderCodexRequest(identity: RuntimeIdentity, scopeId: String, method: String, params: Data?, timeoutMilliseconds: UInt64?, cancellationToken: String?) throws  -> Data

    func agentProviderCodexRespond(identity: RuntimeIdentity, scopeId: String, requestId: Data, result: Data) throws  -> UInt64

    func agentProviderCodexRespondError(identity: RuntimeIdentity, scopeId: String, requestId: Data, code: Int64, message: String, data: Data?) throws  -> UInt64

    func agentProviderCodexState(identity: RuntimeIdentity, scopeId: String) throws  -> CoreCodexSessionStateV1

    /**
     * Returns the immutable, offline P7-4 provider capability profile for a scope.
     */
    func agentProviderConformanceSnapshot(identity: RuntimeIdentity, scopeId: String) throws  -> CoreAgentProviderConformanceSnapshotV1

    func agentProviderOpenScope(identity: RuntimeIdentity, config: CoreAgentProviderScopeConfigV1) throws  -> AgentProviderScopeHandleV1

    /**
     * Sends one already-encoded provider JSON-RPC frame. Rust appends exactly one newline,
     * serializes writes, and returns a monotonic outbound sequence. Provider meaning remains
     * Swift-owned; no protocol-specific request type crosses this boundary.
     */
    func agentProviderSendLine(identity: RuntimeIdentity, scopeId: String, payload: Data) throws  -> UInt64

    /**
     * Idempotent terminal close. Child termination and reaping remain Rust-owned; the generic
     * subscription is closed by the Swift session wrapper so stream lifetime stays explicit.
     */
    func agentProviderShutdown(identity: RuntimeIdentity, scopeId: String) throws

    func agentProviderStart(identity: RuntimeIdentity, scopeId: String) throws  -> AgentProviderStartReceiptV1

    /**
     * Starts a provider scope and writes one raw stdin prompt before closing
     * stdin. This is the Claude Code headless `-p` lifecycle: the child reads
     * the complete prompt, observes EOF, then emits its stream-json result.
     * The prompt is never logged or reinterpreted by the Rust transport.
     */
    func agentProviderStartWithStdin(identity: RuntimeIdentity, scopeId: String, payload: Data) throws  -> AgentProviderStartReceiptV1

    /**
     * Validates a provider scope against the canonical P7-4 profile without starting or
     * inspecting its child process. Invalid profiles are returned as data, not transport errors.
     */
    func agentProviderValidateConformance(identity: RuntimeIdentity, scopeId: String) throws  -> CoreAgentProviderConformanceValidationV1

    /**
     * Contract §7.1's permission **protocol** half only -- policy (auto-approval matching,
     * secure-store decisions) stays Swift/core-owned; this call only encodes and writes the
     * caller's already-decided outcome back to the CLI.
     */
    func agentRespondPermission(identity: RuntimeIdentity, scopeId: String, requestId: String, decision: AgentClaudePermissionDecisionV1) throws

    /**
     * Returns the newly minted `turn_generation` (contract §4's interrupt-fencing token).
     */
    func agentSendUserMessage(identity: RuntimeIdentity, scopeId: String, text: String) throws  -> UInt64

    /**
     * Idempotent: flushes deferred turn completions, escalates SIGTERM -> grace -> SIGKILL against
     * the process group via the shared reaper, then removes the scope from the registry. There is
     * no separate `agent_close_scope` export -- shutdown and close are one terminal operation for
     * this domain (design's seven-export enumeration), unlike `inventory-scope-v1`'s separate
     * open/close pair.
     */
    func agentShutdown(identity: RuntimeIdentity, scopeId: String) throws

    /**
     * Contract §5.1: spawns the child, registers it with the shared reaper, and starts the
     * per-stream reader threads. Returns `pid`/`process_group_id` synchronously so the caller's
     * expected-agent-PID fence (design §4.6) can register immediately on return.
     */
    func agentStartOrResume(identity: RuntimeIdentity, scopeId: String, resumeSessionId: String?, model: String?, effortLevel: String?) throws  -> AgentClaudeStartReceiptV1

    func applyEditsBatchCompactV1(request: CoreApplyEditsBatchRequestV1) throws  -> CoreCompactApplyEditsBatchResultV1

    func beginShutdown(identity: RuntimeIdentity) throws  -> ShutdownReceipt

    func cancelOperation(identity: RuntimeIdentity, operationId: OperationId) throws  -> CancelReceipt

    func closeSubscription(subscriptionId: SubscriptionId) throws

    func codeMapExtractBatchCompactV1(request: CoreCodeMapBatchRequestV1) throws  -> CoreCompactCodeMapBatchResultV1

    func createLeafCancellation(identity: RuntimeIdentity) throws  -> LeafCancellation

    func duplicateWakeReadFd(identity: RuntimeIdentity) throws  -> Int32

    func execute(command: CommandEnvelope) throws  -> AdmissionReceipt

    func fileSystemWatcherCaptureWatermark(identity: RuntimeIdentity, scopeId: String) throws  -> UInt64

    func fileSystemWatcherCloseScope(identity: RuntimeIdentity, scopeId: String) throws

    func fileSystemWatcherIngest(identity: RuntimeIdentity, scopeId: String, entries: [CoreFileSystemWatcherEventV1]) throws  -> UInt64?

    func fileSystemWatcherOpenScope(identity: RuntimeIdentity, config: CoreFileSystemWatcherScopeConfigV1) throws  -> CoreFileSystemWatcherScopeHandleV1

    func fileSystemWatcherReset(identity: RuntimeIdentity, scopeId: String) throws

    func fileSystemWatcherSnapshot(identity: RuntimeIdentity, scopeId: String) throws  -> CoreFileSystemWatcherSnapshotV1

    func fileSystemWatcherStartAccepting(identity: RuntimeIdentity, scopeId: String) throws

    func fileSystemWatcherTakeNext(identity: RuntimeIdentity, scopeId: String, through: UInt64?) throws  -> CoreFileSystemWatcherPayloadV1?

    func filterPaths(request: PathFilterRequest) throws  -> PathFilterResult

    func folderSuffixIndices(request: FolderSuffixRequest) throws  -> [UInt32]

    func initialize() throws  -> CoreHandshake

    func inventoryAbortBulkLoad(identity: RuntimeIdentity, scopeId: String, bulkLoadId: UInt64) throws

    /**
     * Discovery-path counterpart to [`Self::inventory_apply_delta_v1`] (§4.1.1):
     * `command.event_bytes` is the compact discovery delta blob (id-less upserts) --
     * `runtime::inventory_scope::decode_discovery_delta_event`. Mints an id for each upserted
