        /**
         * Largest complete frame, prefix included.
         */maximumFrameBytes: UInt32,
        /**
         * Largest `SnapshotChunk.data` (512 KiB).
         */maximumSnapshotChunkBytes: UInt32,
        /**
         * Largest encoded `AgentSessionSnapshot` (64 MiB).
         */maximumSnapshotBytes: UInt64,
        /**
